import { createModel, parseModelString } from ''./dist/agent/model-provider.js'';
import { generateText, Output } from ''ai'';
import { z } from ''zod'';

const config = parseModelString\(''zhipu/glm-4.7''\);
const model = createModel\(config\);

// Test 2: Structured Output
console.log\(''=== Testing Structured Output ===''\);
try {
  const result = await generateText\({
    model,
    prompt: ''Extract the person info: John is 30 years old and lives in New York.'',
    output: Output.object\({
      schema: z.object\({
        name: z.string\(\),
        age: z.number\(\),
        city: z.string\(\),
      }\),
    }\),
  }\);

  console.log\(''Structured output:'', JSON.stringify\(result.output, null, 2\)\);
} catch \(e\) {
  console.log\(''Structured output ERROR:'', e.message\);
}
")

