import { createModel, parseModelString } from ''./dist/agent/model-provider.js'';
import { generateText, tool } from ''ai'';
import { z } from ''zod'';

const config = parseModelString\(''zhipu/glm-4.7''\);
const model = createModel\(config\);

// Test: Tool-based structured output \(alternative approach\)
console.log\(''=== Testing Tool-Based Structured Output ===''\);
try {
  const result = await generateText\({
    model,
    prompt: ''Extract the person info from this text and call the extract_info tool: John is 30 years old and lives in New York.'',
    tools: {
      extract_info: tool\({
        description: ''Extract structured person information'',
        parameters: z.object\({
          name: z.string\(\).describe\(''Person name''\),
          age: z.number\(\).describe\(''Age in years''\),
          city: z.string\(\).describe\(''City of residence''\),
        }\),
        execute: async \(params\) => params,
      }\),
    },
    toolChoice: ''required'',
  }\);

  console.log\(''Tool calls made:'', result.toolCalls?.length\);
  if \(result.toolResults?.length > 0\) {
    console.log\(''Extracted data:'', JSON.stringify\(result.toolResults[0].output, null, 2\)\);
  }
  if \(result.toolCalls?.length > 0\) {
    console.log\(''Tool call args:'', JSON.stringify\(result.toolCalls[0].args, null, 2\)\);
  }
} catch \(e\) {
  console.log\(''Tool-based structured ERROR:'', e.message\);
}
")
